import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(1, in, out);
        out.close();
    }

    static class Solver {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int l = in.nextInt() - 1;
            int r = in.nextInt() - 1;
            int ab = a + b;
            int[] cc = new int[ab * 4];

            int h = l / ab;
            l -= h * ab;
            r -= h * ab;
            h = (r - l + 1) / ab;
            if (h > 2) {
                r -= (h - 2) * ab;
            }

            int d = a > b ? a - b : 1;

            for (h = 0; h < 4; h++) {
                for (int k = 0; k < a - d; k++) {
                    cc[ab * h + k] = k;
                }
                for (int k = 0; k < d; k++) {
                    cc[ab * h + a - d + k] = h % 2 == 0 ? a - d + k : a + k;
                }
            }

            int[] min = {a + a};
            dfs(0, new int[4], a, b, ab, d, cc, l, r, min);
            out.println(min[0]);
        }

        static void dfs(int step, int[] ks, int a, int b, int ab, int d, int[] cc, int l, int r, int[] min) {
            if (step == 4) {
                for (int block = 0; block < 4; block++) {
                    int val = cc[ab * block + a - ks[block]];
                    int dest = ab * block + a;
                    for (int k = 0; k < b; k++) {
                        cc[dest + k] = val;
                    }
                }
                min[0] = Math.min(min[0], count(cc, l, r));
                return;
            }
            for (int v = 1; v <= d; v++) {
                ks[step] = v;
                dfs(step + 1, ks, a, b, ab, d, cc, l, r, min);
            }
        }

        static int count(int[] cc, int l, int r) {
            boolean[] used = new boolean[24];
            int cnt = 0;
            for (int i = l; i <= r; i++) {
                int c = cc[i];
                if (!used[c]) {
                    used[c] = true;
                    cnt++;
                }
            }
            return cnt;
        }
    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int pnumChars;
        private SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = read();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}
